style.css:
@-moz-document domain("roblox.com") {
/* 1. Ümumi Ana Səhifənin Arxa Fonu */
    body, .container-main, .content {
        background-color: #0f0f12 !important; /* Tünd, estetik qara ton */
        background-image: none !important;
    }

    /* 2. Ana Səhifədəki Oyun və Profil Kartları (Panellər) */
    .section-content, .game-card-container, .home-header {
        background-color: rgba(255, 255, 255, 0.03) !important; /* Şəffaf panel */
        border: 1px solid rgba(255, 255, 255, 0.08) !important; /* Zəif kənar xətti */
        border-radius: 12px !important; /* Kənarların yumşaldılması */
        padding: 15px !important;
    }

    /* 3. Sol Menyunu və Üst Naviqasiya Panelini Uyğunlaşdır */
    #navigation, .navigation, .rbx-header {
        background-color: #13131a !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
    }

    /* 4. Başlıq Mətnləri və İstifadəçi Adının Rəngi */
    h1, h2, h3, .text-title, .home-header a {
        color: #ffffff !important; /* Təmiz bəyaz rəng */
        font-family: "Poppins", "Arial", sans-serif !important;
    }

    /* 5. Keçid Linkləri və Aktiv Menyular */
    .left-col-list li a, .text-link {
        color: #b5b5c3 !important; /* Boz-gümüşü tonlar */
    }
    
    .left-col-list li a:hover {
        color: #ffffff !important;
        background-color: rgba(255, 255, 255, 0.05) !important;
    }
}
